package com.hydrafit.app.core.domain.routine

import com.hydrafit.app.core.domain.engine.SetTarget
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json

/**
 * The training form a cluster prescription describes.
 *
 * Both forms are optional structures the user authors by hand. Neither is inferred from exercise
 * order, and neither is ever generated by a planner engine.
 */
enum class ClusterKind {
    /** Ordered segments with a strictly decreasing external load. */
    DROP_SET,

    /** Ordered segments that repeat one external load with a short rest between them. */
    REST_PAUSE
}

/**
 * One ordered segment of a cluster prescription: the values the user intends for that segment.
 *
 * A segment is rep-based external-load work only. Timed, distance and force measures keep their own
 * exclusive contracts and are not representable here.
 */
@Serializable
data class ClusterSegmentTarget(
    val reps: Int,
    val weightKg: Double,
    /** Prescribed reps in reserve, or null when the user prescribed none. */
    val rir: Int? = null
) {
    fun requireValid() {
        require(reps in MIN_REPS..MAX_REPS) { "A cluster segment needs $MIN_REPS..$MAX_REPS reps" }
        require(weightKg.isFinite() && weightKg > 0.0) {
            "A cluster segment needs a finite positive external load"
        }
        require(rir == null || rir in SetTarget.MIN_RIR..SetTarget.MAX_RIR) {
            "A prescribed cluster RIR must be between ${SetTarget.MIN_RIR} and ${SetTarget.MAX_RIR}"
        }
    }

    companion object {
        const val MIN_REPS: Int = 1
        const val MAX_REPS: Int = 1000
    }
}

/**
 * A slot's ordered cluster prescription.
 *
 * The first segment is the slot's opening work; the remaining segments follow it in order. The
 * cluster occupies **one** prescribed set position, so a slot whose cluster has three segments still
 * asks the user for one thing to complete, not three.
 *
 * [restSeconds] is the intended rest between segments. It is guidance the user authored, never a
 * measured rest, and a null value means the user prescribed none.
 */
@Serializable
data class ClusterPrescription(
    val kind: ClusterKind,
    val segments: List<ClusterSegmentTarget>,
    val restSeconds: Int? = null
) {
    fun requireValid() {
        require(segments.size in MIN_SEGMENTS..MAX_SEGMENTS) {
            "A cluster needs $MIN_SEGMENTS..$MAX_SEGMENTS segments"
        }
        segments.forEach { it.requireValid() }
        val loads = segments.map { it.weightKg }
        when (kind) {
            ClusterKind.DROP_SET -> require(loads.zipWithNext().all { (a, b) -> b < a }) {
                "A drop set needs a strictly decreasing load across its segments"
            }

            ClusterKind.REST_PAUSE -> require(loads.distinct().size == 1) {
                "A rest-pause cluster repeats one load across its segments"
            }
        }
        require(restSeconds == null || restSeconds in 0..Superset.MAX_REST_SECONDS) {
            "Invalid cluster rest"
        }
        if (kind == ClusterKind.REST_PAUSE) {
            require(restSeconds != null && restSeconds > 0) {
                "A rest-pause cluster needs a positive prescribed rest"
            }
        }
    }

    /** The opening segment, which is what the performed parent set records. */
    val openingSegment: ClusterSegmentTarget get() = segments.first()

    val totalReps: Int get() = segments.sumOf { it.reps }

    companion object {
        const val MIN_SEGMENTS: Int = 2
        const val MAX_SEGMENTS: Int = 8
    }
}

/**
 * Strict persisted prescription encoding. A missing value means an ordinary slot, never a cluster
 * inferred from set counts.
 */
object ClusterPrescriptionJson {
    private val json = Json { encodeDefaults = true }

    fun encode(value: ClusterPrescription): String {
        value.requireValid()
        return json.encodeToString(ClusterPrescription.serializer(), value)
    }

    fun decode(text: String): ClusterPrescription =
        json.decodeFromString(ClusterPrescription.serializer(), text).also { it.requireValid() }
}
